// Liga cada item da proposta a um item do pedido original:
//  1) pelo numero_item_pedido que o modelo apontou (ele enxerga o contexto da conversa);
//  2) senao, por semelhanca de texto;
//  3) sem par confiavel, id_item_pedido fica null (item oferecido por fora do pedido).
const pedidos = $('Listar Itens Pedidos').all().map((i) => i.json);
const { dados } = $('Ler JSON da Proposta').first().json;

const limpar = (s) => String(s ?? '').normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase().trim();
const palavras = (s) => s.split(/\s+/).filter(Boolean);

function pontuacao(alvo, candidato) {
  if (alvo === candidato) return 100;
  const um_contem_o_outro = alvo.includes(candidato) || candidato.includes(alvo);
  if (um_contem_o_outro) return 70;
  const palavrasAlvo = new Set(palavras(alvo));
  const palavrasCandidato = palavras(candidato);
  const emComum = palavrasCandidato.filter((p) => palavrasAlvo.has(p)).length;
  return palavrasCandidato.length ? (emComum / palavrasCandidato.length) * 50 : 0;
}

function maisParecido(descricao) {
  const alvo = limpar(descricao);
  let escolhido = null;
  let maior = 0;
  for (const pedido of pedidos) {
    const nota = pontuacao(alvo, limpar(pedido.descricao));
    if (nota > maior) {
      maior = nota;
      escolhido = pedido;
    }
  }
  return maior >= 30 ? escolhido : null;
}

const itens = (dados.itens || []).map((it) => {
  const apontado = it.numero_item_pedido != null ? pedidos.find((p) => p.seq === it.numero_item_pedido) : null;
  const par = apontado || maisParecido(it.descricao);
  return {
    id_item_pedido: par ? par.id : null,
    descricao: it.descricao,
    marca: it.marca ?? null,
    unidade: it.unidade ?? null,
    quantidade: it.quantidade ?? null,
    preco_unit: it.preco_unit ?? null,
    preco_total: it.preco_total ?? null,
    observacao: it.observacao ?? null
  };
});

return [{ json: { itens } }];

// Compara o pedido com a proposta.
//  faltaram: itens pedidos que a proposta nao precificou.
//  sobraram: itens cotados que nao existem no pedido original.
const pedidos = $('Listar Itens Pedidos').all().map((i) => i.json);
const { itens: cotados } = $('Parear Itens com Pedido').first().json;

const cobertos = new Set(cotados.map((c) => c.id_item_pedido).filter((id) => id != null));
const faltaram = pedidos.filter((p) => !cobertos.has(p.id));
const sobraram = cotados.filter((c) => c.id_item_pedido == null);

const marcadores = (lista) => lista.map((x) => `- ${x.descricao}`).join('\n');
const blocos = [];
if (sobraram.length) {
  blocos.push(`Na sua proposta aparecem itens que nao estavam no pedido:\n${marcadores(sobraram)}`);
}
if (faltaram.length) {
  blocos.push(`Estes itens foram pedidos e ficaram sem preco na sua proposta:\n${marcadores(faltaram)}`);
}

const ha_divergencia = blocos.length > 0;
const aviso = ha_divergencia
  ? blocos.join('\n\n') + '\n\nConfirma que e isso mesmo, ou pode mandar um complemento ou correcao?'
  : null;

return [{ json: { ha_divergencia, faltaram, sobraram, aviso } }];

