const { total, respondidos, completa } = $('Contar Convites Respondidos').first().json;
const { codigo_cotacao: codigo } = $('Ler Cabecalho da Cotacao').first().json;

const caption = completa
  ? `Mapa de concorrencia da cotacao ${codigo} completo: as ${total} propostas chegaram.`
  : `Mapa de concorrencia da cotacao ${codigo} atualizado: ${respondidos} de ${total} fornecedores ja responderam.`;

return [{ json: { caption } }];

const cab = $('Ler Cabecalho da Cotacao').first().json;
const pedidos = $('Listar Itens Pedidos').all().map((i) => i.json);
const resumos = $('Ler Resumo por Fornecedor').all().map((i) => i.json);
const cotados = $('Ler Precos Cotados').all().map((i) => i.json);

// o Postgres devolve NUMERIC como texto
const num = (v) => (v == null ? null : Number(v));

// fornecedor -> { id do item pedido -> precos }
const precos = {};
for (const c of cotados) {
  if (c.preco_unit == null && c.preco_total == null) continue;
  precos[c.id_fornecedor] = precos[c.id_fornecedor] || {};
  precos[c.id_fornecedor][String(c.id_item_pedido)] = { preco_unit: num(c.preco_unit), preco_total: num(c.preco_total) };
}

return [{ json: {
  codigo_cotacao: cab.codigo_cotacao,
  obra: cab.obra,
  endereco: cab.endereco,
  itens: pedidos.map((p) => ({
    numero: p.seq,
    id_item_pedido: p.id,
    descricao: p.descricao,
    quantidade: num(p.quantidade),
    unidade: p.unidade
  })),
  fornecedores: resumos.map((r) => ({
    nome: r.nome_fornecedor,
    telefone: r.telefone,
    nome_contato: r.nome_contato,
    itens: precos[r.id_fornecedor] || {},
    total_proposta: num(r.total_proposta),
    valor_frete: num(r.valor_frete),
    valor_imposto: num(r.valor_imposto),
    obs_imposto: r.obs_imposto,
    pct_desconto: num(r.pct_desconto),
    valor_desconto: num(r.valor_desconto),
    forma_pagamento: r.forma_pagamento,
    prazo_servico: r.prazo_servico,
    prazo_material: r.prazo_material,
    validade: r.validade,
    observacoes: r.observacoes
  }))
} }];

const XLSX_MIME = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
const arquivo = await this.helpers.getBinaryDataBuffer(0, 'data');
const codigo = $('Ler Cabecalho da Cotacao').first().json.codigo_cotacao;
const legenda = $('Montar Legenda do Mapa').first().json.caption;

return [{ json: { corpoWaha: {
  session: $('Entrada da Resposta do Fornecedor').first().json.session || 'compras',
  chatId: $('Ler Destino do Mapa').first().json.conversa_engenheiro,
  file: {
    mimetype: XLSX_MIME,
    filename: `Mapa_Concorrencia_${codigo}.xlsx`,
    data: arquivo.toString('base64')
  },
  caption: legenda
} } }];
